/**
 * Unit tests for TreeTraversingParser.getLongValue()
 */
public class TreeTraversingParser_getLongValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }

    /**
     * Tests getLongValue when the current node is a valid LongNumericNode.
     * This covers the standard successful execution path.
     */
    @Test
    public void testGetLongValue_Success() throws IOException {
        JsonNode root = mapper.readTree("1234567890");
        TreeTraversingParser parser = new TreeTraversingParser(root);

        // Move to the number token
        parser.nextToken();

        long value = parser.getLongValue();
        Assert.assertEquals(1234567890L, value);
    }








}

