import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

/**
 * Unit tests for TreeTraversingParser.getLongValue()
 */
public class TreeTraversingParser_getLongValue_TriageGen1Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }



    /**
     * Tests getLongValue when the current node is a NumericNode that cannot be converted to an int,
     * but can be read as a long. This hits the branch where node.canConvertToInt() is false.
     */
    @Test
    public void testGetLongValue_CannotConvertToInt_ButIsLong() throws IOException {
        // A value larger than Integer.MAX_VALUE but fits in Long
        JsonNode root = mapper.readTree("3000000000");
        TreeTraversingParser parser = new TreeTraversingParser(root);

        parser.nextToken();

        // The code contains: if (!node.canConvertToInt()) { ; }
        // This test ensures the branch is covered and the long value is still returned correctly.
        long value = parser.getLongValue();
        Assert.assertEquals(3000000000L, value);
    }






}

